  await page.locator('#publicFormLocation').focus();await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement.id),'publicFormUrl');await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement.dataset.action),'copy-form-link');validUrl(await page.locator('#publicFormUrl').inputValue(),lang,recruiter,'any');await capture(page,width,lang,'expanded');
  await mode(page,'success');await clickCopy(page);await settled(page);assert.equal(await page.locator('#publicFormLinkStatus').innerText(),labels[lang][5]);const copied=await page.locator('#publicFormUrl').inputValue();assert.deepEqual(await page.evaluate(()=>window.__linkCalls),[copied]);assert.equal(await page.evaluate(()=>document.activeElement.dataset.action),'copy-form-link');await capture(page,width,lang,'copied');await preserved(page,before,values,'__originalCandidateForm');
  await page.locator('#publicFormLocation').selectOption(target);assert.equal(await page.locator('#publicFormLinkStatus').innerText(),'');const publicUrl=await page.locator('#publicFormUrl').inputValue();validUrl(publicUrl,lang,recruiter,target);assert.equal(page.url(),urlBefore);
  const manual=[];for(const fault of ['unavailable','denied','getter-denied']){await mode(page,fault);await clickCopy(page);await settled(page);assert.equal(await page.locator('#publicFormLinkStatus').innerText(),labels[lang][6]);assert.equal(await page.evaluate(()=>document.activeElement.id),'publicFormUrl');assert.deepEqual(await page.locator('#publicFormUrl').evaluate(n=>[n.selectionStart,n.selectionEnd]),[0,publicUrl.length]);assert.deepEqual(await page.evaluate(()=>window.__linkCalls),fault==='denied'?[publicUrl]:[]);await preserved(page,before,values,'__originalCandidateForm');if(fault==='unavailable')await capture(page,width,lang,'manual');manual.push({fault,visibleReadonlySelection:true,noFalseSuccess:true,noExecCommandFallback:true});}
