  await mode(page,'deferred');await clickCopy(page);await page.waitForFunction(()=>window.__linkPending!==null);await page.locator('[data-action="language"]').click();assert.equal(await page.locator('#publicFormUrl').count(),0);await page.evaluate(()=>window.__linkPending.reject(new Error('Anonymous fixture late Clipboard refusal')));await page.waitForTimeout(100);assert.equal(await page.locator('#publicFormLinkStatus').count(),0);assert.notEqual(await page.evaluate(()=>document.activeElement.id),'publicFormUrl');await page.locator('#languageSearch').fill(lang);await page.locator(`[data-language="${lang}"]`).click();await page.locator(`[data-recruiter="${recruiter}"]`).click();assert.deepEqual(await answers(page),values);assert.equal(await page.locator('.form-link').evaluate(n=>n.open),false);assert.equal(await page.locator('#publicFormLinkStatus').innerText(),'');assert.equal(await page.evaluate(()=>window.__linkUnrelated()),'KEEP');assert.deepEqual(errors,[]);
