try{
 await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();const matrix=[320,1280].flatMap(width=>Object.keys(labels).map((lang,index)=>({width,lang,index})));let next=0;await Promise.all(Array.from({length:2},async()=>{while(next<matrix.length){const item=matrix[next++];await run(item.width,item.lang,item.index);}}));assert.equal(report.rows.length,40);assert.equal(report.captures.length,120);assert.equal(report.closedViewports.length,40);assert.equal(new Set(report.rows.map(x=>x.recruiter)).size,6);assert.deepEqual(report.external,[]);assert.deepEqual(report.mutations,[]);report.clipboardCases=240;report.applicationDeliveryAttempts=0;report.status='PASSED_40_PUBLIC_FORM_LINK_FLOWS_240_CLIPBOARD_CASES_120_COMPONENTS';
}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();report.finished=new Date().toISOString();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
